const pedido = $('Pedido do script (GET)').first().json;
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 80);
const id = slug((pedido.query || {}).id);
if (id.length < 4) {
  return [{ json: { js: 'console.warn("[métricas] Falta o nome do site (mínimo 4 letras) no endereço do script. Use: lp-script?id=nome-do-seu-site");' } }];
}

// Endereço completo do n8n: assim o script funciona em QUALQUER site, não só nas páginas servidas pelo n8n.
const BASE = String(pedido.webhookUrl || '').split('/webhook/')[0] + '/webhook';

// Este é o script que roda dentro da página, no navegador do visitante.
// O envio vai como texto puro: com 'application/json' o navegador faz uma checagem extra (CORS) e o sendBeacon descarta.
const script = `(function () {
  if (window.__lpm) return; window.__lpm = 1;
  var ID = ${JSON.stringify(id)}, B = ${JSON.stringify(BASE)};
  try { console.info('[métricas] contando visitas, rolagem e cliques para "' + ID + '"'); } catch (e) {}
  var v = '', voltou = false;
  try { v = localStorage.getItem('lpv') || ''; if (!v) { v = Math.random().toString(36).slice(2) + Date.now().toString(36); localStorage.setItem('lpv', v); }
        voltou = !!localStorage.getItem('lpv_' + ID); localStorage.setItem('lpv_' + ID, '1'); } catch (e) {}
  var ini = Date.now(), maxR = 0, cliques = 0, marcos = {}, saiu = false, contatou = false;
  function envia(ev, dados) {
    var c = JSON.stringify(Object.assign({ id: ID, evento: ev, v: v }, dados || {}));
    try { if (navigator.sendBeacon && navigator.sendBeacon(B + '/lp-evento', c)) return; } catch (e) {}
    try { fetch(B + '/lp-evento', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: c, keepalive: true }); } catch (e) {}
  }
  var qs = new URLSearchParams(location.search), ref = '';
  try { ref = document.referrer ? new URL(document.referrer).hostname.replace(/^www\\./, '') : ''; } catch (e) {}
  var origem = qs.get('utm_source') || (ref && ref !== location.hostname ? ref : 'direto');
  envia('visita', { novo: !voltou, origem: origem, disp: /Mobi|Android|iPhone|iPad/i.test(navigator.userAgent) ? 'celular' : 'computador' });
  function rolagem() {
    var total = document.documentElement.scrollHeight - innerHeight, pct = total > 0 ? Math.round(scrollY / total * 100) : 100;
    if (pct > maxR) maxR = pct;
    [25, 50, 75, 100].forEach(function (m) { if (pct >= m - 2 && !marcos[m]) { marcos[m] = 1; envia('rolagem', { marco: m }); } });
  }
  addEventListener('scroll', rolagem, { passive: true }); setTimeout(rolagem, 1500);
  document.addEventListener('click', function (e) {
    if (!e.target.closest || e.target.closest('[data-lpm-ignorar]')) return;
    var marcado = e.target.closest('[data-metrica]');
    if (marcado) { cliques++; envia('clique', { tipo: 'marcado', rotulo: String(marcado.getAttribute('data-metrica')).slice(0, 40) }); return; }
    var a = e.target.closest('a,button'); if (!a || a.type === 'submit') return;
    var h = a.getAttribute('href') || '', tipo = 'botao';
    if (/wa\\.me|whatsapp/i.test(h)) tipo = 'whatsapp'; else if (/^tel:/i.test(h)) tipo = 'telefone'; else if (/^mailto:/i.test(h)) tipo = 'email';
    else if (/instagram\\.com/i.test(h)) tipo = 'instagram'; else if (h.charAt(0) === '#') tipo = 'menu'; else if (/^https?:/i.test(h)) tipo = 'link_externo';
    // "primeiro": só o 1º clique de contato da visita, para contar PESSOAS que chamaram (e não cliques repetidos)
    var primeiro = /whatsapp|telefone|email/.test(tipo) && !contatou; if (primeiro) contatou = true;
    cliques++; envia('clique', { tipo: tipo, primeiro: primeiro, rotulo: (a.innerText || a.getAttribute('aria-label') || '').replace(/\\s+/g, ' ').trim().slice(0, 40) });
  }, true);
  function sai() { if (saiu) return; saiu = true; envia('saida', { segundos: Math.round((Date.now() - ini) / 1000), rolagem: maxR }); }
  addEventListener('pagehide', sai);
  document.addEventListener('visibilitychange', function () { if (document.visibilityState === 'hidden') sai(); });
  document.addEventListener('submit', function (e) {
    var f = e.target, campos = {}; if (!f || !f.querySelectorAll) return;
    f.querySelectorAll('input,textarea,select').forEach(function (el, i) {
      if (!el.value || /hidden|password|submit|button/.test(el.type)) return;
      var r = (el.labels && el.labels[0] && el.labels[0].innerText) || el.getAttribute('aria-label') || el.name || el.placeholder || el.type || 'campo' + i;
      campos[r.replace(/\\s+/g, ' ').trim().slice(0, 40)] = String(el.value).slice(0, 600);
    });
    if (!Object.keys(campos).length) return;
    var d = document.querySelector('meta[name="description"]');
    var c = JSON.stringify({ id: ID, v: v, campos: campos, origem: origem,
      pagina: { titulo: document.title.slice(0, 120), descricao: (d && d.content || '').slice(0, 300), url: location.href.split('#')[0] },
      engajamento: { segundos: Math.round((Date.now() - ini) / 1000), rolagem: maxR, cliques: cliques, voltou: voltou } });
    try { fetch(B + '/lp-lead', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: c, keepalive: true }); } catch (x) {}
    envia('lead');
  }, true);
})();`;
return [{ json: { js: script } }];

// Página de exemplo (uma padaria de mentira) com o código das métricas instalado, igual a um site de verdade.
const pedido = $('Pedido da página de teste (GET)').first().json;
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 80);
const id = slug((pedido.query || {}).id);
const base = String(pedido.webhookUrl || '').split('/webhook/')[0];
if (id.length < 4) {
  // Sem o nome do site: manda para a tela "Comece aqui", que gera o nome.
  const inicio = base + '/webhook/lp-metricas';
  return [{ json: { codigo: 200, html: `<!DOCTYPE html><meta charset="UTF-8"><meta http-equiv="refresh" content="0;url=${inicio}"><a href="${inicio}">Comece aqui</a>` } }];
}
const painel = `${base}/webhook/lp-metricas?id=${id}`;
const produtos = [
  ['🥖', 'Pão francês', 'Saindo do forno a cada 2 horas', 'R$ 0,90'],
  ['🧀', 'Pão de queijo', 'Receita mineira, crocante por fora', 'R$ 4,50'],
  ['🍰', 'Bolo de cenoura', 'Com cobertura de chocolate de verdade', 'R$ 32,00'],
  ['🥐', 'Croissant', 'Manteiga francesa, 36 camadas', 'R$ 9,00'],
  ['☕', 'Café coado', 'Grãos do sul de Minas', 'R$ 6,00'],
  ['🍩', 'Sonho', 'Recheio de creme ou doce de leite', 'R$ 7,50'],
];

const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">
<title>Padaria Pão Quente (página de teste)</title>
<meta name="description" content="Página de exemplo para testar o painel de métricas.">
<style>
:root{--creme:#fbf6ee;--marrom:#5a3418;--tx:#2b1d12;--tx2:#6b5646;--dourado:#c9822b;--borda:rgba(43,29,18,.12)}
