.faixa-teste a{color:#1c5cab;background:#fff;text-decoration:none;padding:6px 12px;border-radius:8px;font-weight:700}
header{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;max-width:1000px;margin:0 auto;padding:18px 16px}
.logo{font-size:22px;font-weight:700;color:var(--marrom)}
nav{display:flex;gap:16px;flex-wrap:wrap}nav a{color:var(--tx2);text-decoration:none;font:15px system-ui,sans-serif}
.hero{max-width:1000px;margin:0 auto;padding:56px 16px 64px;text-align:center}
.hero h1{font-size:clamp(32px,6vw,52px);line-height:1.1;color:var(--marrom)}
.hero p{font-size:19px;color:var(--tx2);max-width:560px;margin:16px auto 0}
.botoes{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:28px}
