summary{cursor:pointer;font-weight:700}
.contato{text-align:center;background:var(--marrom);color:#fff;border-radius:24px;margin:40px auto 60px;max-width:968px}
.contato h2{color:#fff}.contato p{color:#f1e3d3}
.contato .b{border-color:#fff;color:#fff}
