<section id="contato" class="contato"><h2>Bateu a fome?</h2><p>Chame no WhatsApp ou ligue. Atendemos das 6h às 20h.</p>
<div class="botoes"><a class="b zap" href="https://wa.me/?text=Oi%2C%20quero%20fazer%20um%20pedido" target="_blank" rel="noopener">💬 Chamar no WhatsApp</a>
<a class="b" href="tel:+5500000000000">📞 Ligar agora</a></div></section>

<footer>Padaria Pão Quente é um exemplo fictício para testar as métricas.</footer>
</body></html>`;
return [{ json: { codigo: 200, html } }];

let b = $('Evento chega (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const id = String(b.id || '').toLowerCase();
const EVENTOS = ['visita', 'rolagem', 'clique', 'saida', 'lead'];
if (!/^[a-z0-9-]{4,80}$/.test(id) || !EVENTOS.includes(b.evento)) return [];

// "permitidos" deixa passar o ponto na origem, para "instagram.com" não virar "instagram-com"
const slug = (s, permitidos = 'a-z0-9') => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(new RegExp(`[^${permitidos}]+`, 'g'), '-').replace(/(^-|-$)/g, '').slice(0, 40) || 'sem-nome';
const dia = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const k = s => `mt:${id}:${s}`;
const chaves = [];

if (b.evento === 'visita') {
  chaves.push(k('visitas'), k('dia:' + dia));
  if (b.novo) chaves.push(k('visitantes'));
  chaves.push(k('disp:' + (b.disp === 'celular' ? 'celular' : 'computador')), k('origem:' + slug(b.origem, 'a-z0-9.')));
} else if (b.evento === 'rolagem') {
  const m = Number(b.marco);
  if ([25, 50, 75, 100].includes(m)) chaves.push(k('rolagem:' + m));
} else if (b.evento === 'clique') {
  const tipos = ['whatsapp', 'telefone', 'email', 'instagram', 'menu', 'link_externo', 'botao', 'marcado'];
  chaves.push(k('clique:' + (tipos.includes(b.tipo) ? b.tipo : 'botao')));
  if (b.primeiro === true) chaves.push(k('pessoas_contato'));
  const rotulo = String(b.rotulo || '').toLowerCase().replace(/[\s:*?\[\]]+/g, ' ').trim().slice(0, 40);
  if (rotulo) chaves.push(k('botao:' + rotulo));
} else if (b.evento === 'saida') {
  const s = Number(b.segundos) || 0;
  chaves.push(k('tempo:' + (s < 10 ? 'a_0-10s' : s < 30 ? 'b_10-30s' : s < 60 ? 'c_30-60s' : s < 180 ? 'd_1-3min' : 'e_3min+')));
} else if (b.evento === 'lead') {
  chaves.push(k('leads'));
}
return chaves.map(chave => ({ json: { chave } }));

// Aceita o nome do site do jeito que a pessoa digitar ("Padaria do João" vira "padaria-do-joao").
const q = $('Painel de métricas (GET)').first().json.query || {};
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 80);
const id = slug(q.id);
return [{ json: { id, tem_id: id.length >= 4, ia: q.ia === '1', digitado: String(q.id || '').slice(0, 80) } }];

// Tela "Comece aqui": aparece quando o painel é aberto sem o nome do site.
const p = $('Entende o pedido').first().json;
const base = String($('Painel de métricas (GET)').first().json.webhookUrl || '').split('/webhook/')[0];
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Este código roda no navegador de quem abriu a tela (vai para a página como texto com .toString()).
function cliente(BASE) {
  var el = function (s) { return document.querySelector(s); };
  var sufixo = Math.random().toString(36).slice(2, 6);
  function slug(s) {
    return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 60);
  }
  function atualiza() {
    var nome = slug(el('#nome').value);
    var id = nome ? nome + (el('#sufixo').checked ? '-' + sufixo : '') : '';
    var ok = id.length >= 4;
    var painel = BASE + '/webhook/lp-metricas?id=' + id;
    el('#codigo').textContent = ok ? id : '…';
    el('#snippet').textContent = ok ? '<script src="' + BASE + '/webhook/lp-script?id=' + id + '" defer><\/script>' : 'Digite o nome do site no passo 1 (mínimo 4 letras)';
    el('#painel-url').textContent = ok ? painel : '…';
    el('#teste').href = ok ? BASE + '/webhook/lp-teste?id=' + id : '#';
    el('#painel').href = ok ? painel : '#';
    document.body.classList.toggle('pronto', ok);
  }
  el('#nome').addEventListener('input', atualiza);
  el('#sufixo').addEventListener('change', atualiza);
  document.addEventListener('click', function (e) {
    var b = e.target.closest('[data-copiar]');
    if (b) {
      var alvo = el(b.getAttribute('data-copiar'));
      var volta = function () { b.textContent = '✅ Copiado'; setTimeout(function () { b.textContent = b.getAttribute('data-rotulo'); }, 1800); };
      if (navigator.clipboard) navigator.clipboard.writeText(alvo.textContent).then(volta, function () {});
      else { var r = document.createRange(); r.selectNodeContents(alvo); getSelection().removeAllRanges(); getSelection().addRange(r); document.execCommand('copy'); volta(); }
    }
    var trava = e.target.closest('.trava');
    if (trava && !document.body.classList.contains('pronto')) { e.preventDefault(); el('#nome').focus(); }
  });
  atualiza();
}

const aviso = p.digitado
  ? `<div class="aviso">⚠️ O nome <b>${esc(p.digitado)}</b> é curto demais. Use pelo menos 4 letras ou números.</div>` : '';

const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">
<title>Métricas do seu site · Comece aqui</title>
<style>
:root{color-scheme:light;--plano:#f9f9f7;--sup:#fcfcfb;--tx:#0b0b0b;--tx2:#52514e;--mu:#898781;--borda:rgba(11,11,11,.12);--pri:#1c5cab;--pri-tx:#fff;--cod:#f1f0ec;--ok:#0a7d0a;--alerta:#8a5a00;--alerta-bg:#fff4d6}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){color-scheme:dark;--plano:#0d0d0d;--sup:#1a1a19;--tx:#f0efec;--tx2:#c3c2b7;--mu:#898781;--borda:rgba(255,255,255,.12);--pri:#3987e5;--cod:#232322;--ok:#5fd35f;--alerta:#fab219;--alerta-bg:#2a2210}}
:root[data-theme="dark"]{color-scheme:dark;--plano:#0d0d0d;--sup:#1a1a19;--tx:#f0efec;--tx2:#c3c2b7;--borda:rgba(255,255,255,.12);--pri:#3987e5;--cod:#232322;--ok:#5fd35f;--alerta:#fab219;--alerta-bg:#2a2210}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--plano);color:var(--tx);line-height:1.5;padding:28px 16px 64px}
.w{max-width:760px;margin:0 auto}
h1{font-size:28px;font-weight:700;letter-spacing:-.01em}
.sub{color:var(--tx2);margin-top:6px;font-size:15.5px}
.passo{background:var(--sup);border:1px solid var(--borda);border-radius:16px;padding:20px;margin-top:16px}
.passo h2{font-size:17px;display:flex;gap:10px;align-items:center}
.n{flex:none;width:28px;height:28px;border-radius:50%;background:var(--pri);color:var(--pri-tx);display:grid;place-items:center;font-size:14px;font-weight:700}
.passo p,.passo li{color:var(--tx2);font-size:14.5px;margin-top:8px}
label{display:block;font-weight:600;font-size:14px;margin-top:12px}
input[type=text]{width:100%;margin-top:6px;font:inherit;font-size:17px;padding:12px 14px;border-radius:12px;border:1px solid var(--borda);background:var(--plano);color:var(--tx)}
input[type=text]:focus{outline:3px solid color-mix(in srgb,var(--pri) 35%,transparent);border-color:var(--pri)}
.chk{display:flex;gap:8px;align-items:flex-start;font-weight:500;color:var(--tx2);font-size:13.5px;margin-top:10px}
.chk input{margin-top:3px}
.cod{display:block;background:var(--cod);border:1px solid var(--borda);border-radius:10px;padding:12px 14px;font:13.5px/1.5 ui-monospace,Consolas,monospace;word-break:break-all;margin-top:10px;color:var(--tx)}
.linha{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:10px}
.btn{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--borda);background:var(--sup);color:var(--tx);text-decoration:none;font:inherit;font-weight:600;font-size:14.5px;padding:10px 16px;border-radius:11px;cursor:pointer}
