        voltou = !!localStorage.getItem('lpv_' + ID); localStorage.setItem('lpv_' + ID, '1'); } catch (e) {}
  var ini = Date.now(), maxR = 0, cliques = 0, marcos = {}, saiu = false, contatou = false;
  function envia(ev, dados) {
    var c = JSON.stringify(Object.assign({ id: ID, evento: ev, v: v }, dados || {}));
    try { if (navigator.sendBeacon && navigator.sendBeacon(B + '/lp-evento', c)) return; } catch (e) {}
    try { fetch(B + '/lp-evento', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: c, keepalive: true }); } catch (e) {}
  }
  var qs = new URLSearchParams(location.search), ref = '';
