  }).join('');
};
const nomeOrigem = s => s === 'direto' ? 'Direto (link ou digitado)' : s;
const ROT = { whatsapp: 'WhatsApp', telefone: 'Telefone', email: 'E-mail', instagram: 'Instagram', menu: 'Menu da página', link_externo: 'Links externos', botao: 'Outros botões', marcado: 'Marcados (data-metrica)' };

let ia = null;
try { if ($('IA Analista').isExecuted) ia = parseJSON($('IA Analista').first().json.output); } catch (e) {}

const p = m.pagina || {};
const maxDia = Math.max(...m.dias.map(d => d.visitas));
const colunas = m.dias.map((d, i) => `<div class="col"><i tabindex="0" data-tip="${d.semana} ${d.dia}: ${num(d.visitas)} visita${d.visitas === 1 ? '' : 's'}" style="height:${maxDia && d.visitas ? Math.max(1.5, d.visitas / maxDia * 100) : 0}%;${d.visitas ? '' : 'min-height:0'}"></i>${d.visitas === maxDia && maxDia > 0 ? `<em style="bottom:calc(${d.visitas / maxDia * 100}% + 4px)">${num(d.visitas)}</em>` : ''}</div>`).join('');
const rotX = m.dias.map((d, i) => `<span>${i % 2 === 1 || i === 13 ? d.dia : ''}</span>`).join('');
const cliquesLista = Object.entries(m.cliques).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]).map(([k, v]) => [ROT[k] || k, v]);
const funilCores = ['var(--f1)', 'var(--f2)', 'var(--f3)', 'var(--f4)', 'var(--f5)'];

let blocoIA = '';
if (ia) {
  const n = Math.max(0, Math.min(100, Number(ia.nota_saude) || 0));
  const st = n >= 70 ? ['var(--bom)', '✅', 'Saudável'] : n >= 40 ? ['var(--alerta)', '⚠️', 'Pode melhorar'] : ['var(--critico)', '🔴', 'Precisa de atenção'];
  const lista = arr => (Array.isArray(arr) ? arr : []).slice(0, 5).map(x => `<li>${esc(typeof x === 'string' ? x : x.titulo || '')}${x && x.porque ? ` <span>· ${esc(x.porque)}</span>` : ''}</li>`).join('');
  blocoIA = `<div class="card c12 ia"><h2>🤖 Análise da IA</h2><div class="saude"><span class="ponto" style="background:${st[0]}"></span>${st[1]} ${st[2]} · nota ${n} de 100</div>
  <p style="color:var(--tx2)">${esc(ia.resumo)}</p>
  <h3>💪 O que está funcionando</h3><ul>${lista(ia.pontos_fortes)}</ul>
  <h3>🚧 Onde as pessoas desistem</h3><ul>${lista(ia.gargalos)}</ul>
  <h3>🎯 O que fazer agora</h3><ul>${(Array.isArray(ia.acoes) ? ia.acoes : []).slice(0, 4).map(a => `<li><b>${esc(a.titulo)}</b>${a.porque ? ` · ${esc(a.porque)}` : ''}</li>`).join('')}</ul></div>`;
} else if ($('Calcular métricas').first().json.quer_ia) {
  blocoIA = `<div class="card c12 ia"><h2>🤖 Análise da IA</h2><p class="vazio">A IA não respondeu agora. Tente de novo em instantes.</p></div>`;
}

const todos = [['Visitas', m.visitas], ['Visitantes únicos', m.visitantes], ...m.funil.slice(1).map(f => [f.etapa, f.qtd]),
  ...Object.entries(m.cliques).map(([k, v]) => ['Cliques · ' + (ROT[k] || k), v]), ...m.tempo.map(t => ['Tempo · ' + t.faixa, t.qtd]),
  ...m.origens.map(([k, v]) => ['Origem · ' + nomeOrigem(k), v]), ...m.dispositivos.map(([k, v]) => ['Aparelho · ' + k, v])];

const corpo = `
<h1>📊 Métricas · ${esc(p.empresa || m.id)}</h1>
<p class="sub">Atualizado às ${new Date().toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' })} · cada visita, rolagem e clique é contado em tempo real</p>
<div class="acoes">${p.url ? `<a class="btn" href="${esc(p.url)}" target="_blank" rel="noopener">🔗 Abrir a página</a>` : ''}
${m.visitas ? `<a class="btn pri" href="?id=${esc(m.id)}&ia=1">🤖 Analisar com IA</a>` : ''}
<a class="btn" href="${esc(base)}/webhook/lp-leads?id=${esc(m.id)}">🎯 Ver leads</a>
<a class="btn" href="?id=${esc(m.id)}">🔄 Atualizar</a></div>
${m.visitas === 0 ? `<div class="grid"><div class="card c12 espera"><h2>⏳ Esperando a primeira visita</h2>
<p class="sub">${p.url ? 'O código já está instalado nesta landing page. Abra a página e role um pouco.' : 'Instale o código abaixo no seu site (ou use a página de teste) e abra o site.'} Depois clique em <b>🔄 Atualizar</b>: os números aparecem em segundos.</p></div>
<div class="card c12"><h2>🔧 Como instalar</h2>${instalar}</div></div>` : `
<div class="grid">
  <div class="card tile hero c3"><div class="lab">Visitas</div><div class="val">${num(m.visitas)}</div><div class="det">últimos 180 dias</div></div>
  <div class="card tile c3"><div class="lab">Visitantes únicos</div><div class="val">${num(m.visitantes)}</div><div class="det">pessoas diferentes</div></div>
  <div class="card tile c3"><div class="lab">Rolaram até o fim</div><div class="val">${m.taxa_fim.toString().replace('.', ',')}%</div><div class="det">das visitas viram a página toda</div></div>
  <div class="card tile c3"><div class="lab">Contatos</div><div class="val">${num(m.contato + m.leads)}</div><div class="det">${m.taxa_contato.toString().replace('.', ',')}% dos visitantes chamaram</div></div>
  ${blocoIA}
  <div class="card c8"><h2>🔻 Funil da página</h2><p class="sub">Quantas pessoas chegaram em cada etapa, do total de visitas</p>${barras(m.funil.map(f => [f.etapa, f.qtd]), i => funilCores[i], m.visitas)}</div>
  <div class="card c4"><h2>🖱️ Cliques por tipo</h2>${cliquesLista.length ? barras(cliquesLista, 'var(--s1)') : '<p class="vazio">Nenhum clique ainda.</p>'}</div>
  <div class="card c12"><h2>📅 Visitas por dia</h2><p class="sub">Últimos 14 dias · passe o mouse nas colunas</p><div class="cols">${colunas}</div><div class="xl">${rotX}</div></div>
  <div class="card c6"><h2>🏷️ Botões mais clicados</h2>${m.botoes.length ? barras(m.botoes, 'var(--s1)') : '<p class="vazio">Nenhum botão clicado ainda.</p>'}</div>
  <div class="card c6"><h2>⏱️ Tempo na página</h2>${m.tempo.some(t => t.qtd) ? barras(m.tempo.map(t => [t.faixa, t.qtd]), 'var(--s1)') : '<p class="vazio">Aparece quando os visitantes saem da página.</p>'}</div>
  <div class="card c6"><h2>🌐 De onde vieram</h2>${barras(m.origens.map(([k, v]) => [nomeOrigem(k), v]), 'var(--s1)', m.visitas)}</div>
  <div class="card c6"><h2>📱 Aparelho</h2>${barras(m.dispositivos.map(([k, v]) => [k === 'celular' ? 'Celular' : 'Computador', v]), 'var(--s1)', m.visitas)}</div>
</div>
<details class="card"><summary>Ver todos os números em tabela</summary><table><thead><tr><th>Métrica</th><th>Quantidade</th></tr></thead><tbody>${todos.map(([a, b]) => `<tr><td>${esc(a)}</td><td>${num(b)}</td></tr>`).join('')}</tbody></table></details>
<details class="card"><summary>🔧 Código de instalação e página de teste</summary>${instalar}</details>`}`;
return [{ json: { codigo: 200, html: casca('Métricas · ' + (p.empresa || m.id), corpo) } }];
